-- Functional starter content for emulator walkthroughs. This original project
-- content has an internal technical pass but does not replace the larger,
-- independently reviewed faculty-release bank.

INSERT INTO question(id,family_id,version,topic_id,type,difficulty,prompt,options,answer,explanation,criteria,source,license,author,reviewer,state) VALUES
('starter-dsa-e-01','starter-dsa-e-01',1,'dsa-arrays','MCQ','EASY','What is the usual time complexity of reading arr[i] from an array?','["O(1)","O(log n)","O(n)","O(n log n)"]','O(1)','An array computes an element address directly from its index.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-dsa-e-02','starter-dsa-e-02',1,'dsa-stacks','MCQ','EASY','Which operation removes the most recently added stack element?','["pop","dequeue","peek","search"]','pop','A stack follows last-in, first-out order; pop removes its top element.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-dsa-e-03','starter-dsa-e-03',1,'dsa-linked','MCQ','EASY','What does a singly linked node store besides its value?','["A link to the next node","The full list","A parent node","A hash table"]','A link to the next node','A singly linked node contains data and a reference to its successor.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-dsa-e-04','starter-dsa-e-04',1,'dsa-trees','MCQ','EASY','Which node has no parent in a tree?','["Root","Leaf","Sibling","Child"]','Root','The root is the starting node and has no parent.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-dsa-e-05','starter-dsa-e-05',1,'dsa-search-sort','MCQ','EASY','Which search requires sorted input?','["Binary search","Linear search","Breadth-first search","Depth-first search"]','Binary search','Binary search discards half of a sorted range after each comparison.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-dsa-m-01','starter-dsa-m-01',1,'dsa-arrays','MCQ','MEDIUM','What is the worst-case time to insert at the start of an array-backed list?','["O(n)","O(1)","O(log n)","O(n log n)"]','O(n)','Existing elements generally need to shift one position.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-dsa-m-02','starter-dsa-m-02',1,'dsa-stacks','MCQ','MEDIUM','Which structure is normally used for breadth-first traversal?','["Queue","Stack","Heap","Set"]','Queue','A queue processes nodes in discovery order.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-dsa-m-03','starter-dsa-m-03',1,'dsa-linked','MCQ','MEDIUM','Given only a list head, what is worst-case lookup by position?','["O(n)","O(1)","O(log n)","O(n log n)"]','O(n)','The list may require traversal from the head to the requested position.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-dsa-m-04','starter-dsa-m-04',1,'dsa-trees','MCQ','MEDIUM','Which traversal of a binary search tree returns keys in sorted order?','["In-order","Pre-order","Post-order","Level-order"]','In-order','In-order visits the left subtree, node and then right subtree.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-dsa-m-05','starter-dsa-m-05',1,'dsa-search-sort','MCQ','MEDIUM','What is merge sort worst-case time complexity?','["O(n log n)","O(n squared)","O(log n)","O(n)"]','O(n log n)','Merge sort has logarithmic levels and linear merging work per level.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-dsa-h-01','starter-dsa-h-01',1,'dsa-arrays','MCQ','HARD','Which technique finds a maximum-sum contiguous subarray in linear time?','["Kadane algorithm","Dijkstra algorithm","Kruskal algorithm","KMP algorithm"]','Kadane algorithm','Kadane algorithm tracks the best subarray ending at each position.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-dsa-h-02','starter-dsa-h-02',1,'dsa-stacks','MCQ','HARD','A monotonic stack commonly helps find which value efficiently?','["The next greater element","A minimum spanning tree","A string hash","A database key"]','The next greater element','A monotonic stack discards elements that cannot be the next answer.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-dsa-h-03','starter-dsa-h-03',1,'dsa-linked','MCQ','HARD','Floyd cycle detection uses which pointer speeds?','["One step and two steps","One step and three steps","Two equal speeds","Random speeds"]','One step and two steps','If a cycle exists, a slow and a fast pointer eventually meet inside it.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-dsa-h-04','starter-dsa-h-04',1,'dsa-trees','MCQ','HARD','What is the height bound of an AVL tree with n nodes?','["O(log n)","O(n)","O(n log n)","O(1)"]','O(log n)','AVL rotations maintain logarithmic height.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-dsa-h-05','starter-dsa-h-05',1,'dsa-search-sort','MCQ','HARD','Which sort is stable with guaranteed O(n log n) worst-case time?','["Merge sort","Quick sort","Heap sort","Selection sort"]','Merge sort','Standard merge sort preserves equal-key order and guarantees n log n time.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),

('starter-db-e-01','starter-db-e-01',1,'dbms-relational','MCQ','EASY','What uniquely identifies a row in a relational table?','["Primary key","View","Index page","Foreign table"]','Primary key','A primary key uniquely identifies each row.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-db-e-02','starter-db-e-02',1,'dbms-sql','MCQ','EASY','Which SQL command reads rows from a table?','["SELECT","UPDATE","DELETE","DROP"]','SELECT','SELECT retrieves columns and rows from one or more sources.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-db-e-03','starter-db-e-03',1,'dbms-normalization','MCQ','EASY','First normal form requires each field to contain what?','["An atomic value","A nested table","Multiple lists","A derived total"]','An atomic value','First normal form removes repeating groups and requires atomic values.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-db-e-04','starter-db-e-04',1,'dbms-transactions','MCQ','EASY','Which transaction command makes changes permanent?','["COMMIT","ROLLBACK","SELECT","SAVEPOINT"]','COMMIT','COMMIT completes the transaction and makes its changes durable.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-db-e-05','starter-db-e-05',1,'dbms-indexing','MCQ','EASY','What is the main purpose of a database index?','["Speed up data lookup","Encrypt every row","Replace backups","Remove constraints"]','Speed up data lookup','An index provides an access path that can avoid scanning every row.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-db-m-01','starter-db-m-01',1,'dbms-relational','MCQ','MEDIUM','What does a foreign key enforce?','["Referential integrity","Sort order","Column encryption","Automatic backups"]','Referential integrity','It requires referenced values to correspond to an allowed parent key.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-db-m-02','starter-db-m-02',1,'dbms-sql','MCQ','MEDIUM','Which join keeps every row from the left table?','["LEFT JOIN","INNER JOIN","CROSS JOIN","SELF JOIN"]','LEFT JOIN','A left join retains unmatched left rows and fills right columns with nulls.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-db-m-03','starter-db-m-03',1,'dbms-normalization','MCQ','MEDIUM','Third normal form primarily removes what dependency?','["Transitive dependency on a key","Every foreign key","All candidate keys","Every nullable column"]','Transitive dependency on a key','In 3NF, non-key attributes should not depend transitively on a key.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-db-m-04','starter-db-m-04',1,'dbms-transactions','MCQ','MEDIUM','Which ACID property controls visibility between concurrent transactions?','["Isolation","Atomicity","Consistency","Durability"]','Isolation','Isolation controls interference and visibility between transactions.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-db-m-05','starter-db-m-05',1,'dbms-indexing','MCQ','MEDIUM','Why can too many indexes slow writes?','["Each affected index must be maintained","Indexes disable transactions","Indexes duplicate the process","Every index locks all tables"]','Each affected index must be maintained','Writes may need changes in several index structures.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-db-h-01','starter-db-h-01',1,'dbms-relational','MCQ','HARD','Which relational operation removes duplicate rows by definition?','["Projection","Cartesian product","Theta join","Rename"]','Projection','Classical relational algebra projection produces a set.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-db-h-02','starter-db-h-02',1,'dbms-sql','MCQ','HARD','What does a correlated subquery depend on?','["Values from the outer query row","Only its constants","A separate server","A materialized view only"]','Values from the outer query row','A correlated subquery references columns from the enclosing query.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-db-h-03','starter-db-h-03',1,'dbms-normalization','MCQ','HARD','BCNF requires every non-trivial determinant to be what?','["A superkey","A foreign key","Nullable","A composite key"]','A superkey','BCNF requires each non-trivial functional dependency determinant to be a superkey.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-db-h-04','starter-db-h-04',1,'dbms-transactions','MCQ','HARD','Which anomaly occurs when one row is read twice with different committed values?','["Non-repeatable read","Dirty read","Lost schema","Phantom lock"]','Non-repeatable read','Another transaction commits an update between the two reads.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-db-h-05','starter-db-h-05',1,'dbms-indexing','MCQ','HARD','A composite index on (a,b) most directly supports which predicate?','["a = ? AND b = ?","b = ? only","c = ? only","NOT a without comparison"]','a = ? AND b = ?','A B-tree composite index is naturally usable from its leftmost prefix.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),

('starter-os-e-01','starter-os-e-01',1,'os-processes','MCQ','EASY','What is a running program called?','["Process","Page","File descriptor","Semaphore"]','Process','A process is a program in execution with its runtime state.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-os-e-02','starter-os-e-02',1,'os-scheduling','MCQ','EASY','Which scheduler serves processes in arrival order?','["First-come, first-served","Round robin","Shortest remaining time","Priority preemption"]','First-come, first-served','FCFS selects the ready process that arrived first.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-os-e-03','starter-os-e-03',1,'os-synchronization','MCQ','EASY','What does a mutex protect?','["A critical section","A disk partition","A compiled class","A network address"]','A critical section','A mutex allows only one owner at a time to access protected state.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-os-e-04','starter-os-e-04',1,'os-deadlocks','MCQ','EASY','In deadlock, blocked processes wait for what?','["Resources held within the waiting cycle","A timer only","User input only","Compiler output"]','Resources held within the waiting cycle','Each process waits for a resource held by another participant.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-os-e-05','starter-os-e-05',1,'os-memory','MCQ','EASY','Virtual memory commonly uses which fixed-size unit?','["Page","Thread","Socket","Instruction"]','Page','Paging divides virtual and physical memory into pages and frames.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-os-m-01','starter-os-m-01',1,'os-processes','MCQ','MEDIUM','Threads in one process normally share which resource?','["Address space","Program counter","Call stack","CPU register set"]','Address space','Threads share the process address space but keep separate execution state.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-os-m-02','starter-os-m-02',1,'os-scheduling','MCQ','MEDIUM','Which scheduling algorithm uses a time quantum?','["Round robin","First-come, first-served","Non-preemptive priority","Shortest job first"]','Round robin','Round robin preempts a process when its time slice expires.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-os-m-03','starter-os-m-03',1,'os-synchronization','MCQ','MEDIUM','What can occur when threads update shared data without synchronization?','["Race condition","Page compression","Internal fragmentation","Spooling"]','Race condition','The result can depend on unpredictable operation interleaving.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-os-m-04','starter-os-m-04',1,'os-deadlocks','MCQ','MEDIUM','Which is one Coffman condition for deadlock?','["Circular wait","Infinite memory","Fair scheduling","Stateless processes"]','Circular wait','Deadlock requires a cycle in which each participant waits for the next.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-os-m-05','starter-os-m-05',1,'os-memory','MCQ','MEDIUM','What triggers a page fault?','["A referenced page is not in physical memory","A thread releases a mutex","A file is renamed","A CPU quantum expires"]','A referenced page is not in physical memory','The OS must resolve the missing mapping, often by loading the page.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-os-h-01','starter-os-h-01',1,'os-processes','MCQ','HARD','Copy-on-write after fork delays copying until what happens?','["A process writes to a shared page","The child exits","The quantum changes","A file is opened"]','A process writes to a shared page','Read-only sharing continues until a writer requires a private copy.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-os-h-02','starter-os-h-02',1,'os-scheduling','MCQ','HARD','What issue can aging reduce in priority scheduling?','["Starvation","Deadlock detection","Page faults","Context storage"]','Starvation','Aging raises the priority of processes that wait for a long time.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-os-h-03','starter-os-h-03',1,'os-synchronization','MCQ','HARD','A counting semaphore initialized to N can permit how many concurrent holders?','["Up to N","Exactly one","None","Unlimited"]','Up to N','Its count represents the available permits.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-os-h-04','starter-os-h-04',1,'os-deadlocks','MCQ','HARD','Banker algorithm grants requests only when the resulting state remains what?','["Safe","Preemptive","Paged","Idle"]','Safe','A safe state has some completion order for all processes.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED'),
('starter-os-h-05','starter-os-h-05',1,'os-memory','MCQ','HARD','What does a TLB cache?','["Recent virtual-to-physical translations","File contents","Process source code","Disk requests"]','Recent virtual-to-physical translations','A TLB speeds address translation by caching page-table results.','[]','InterviewEdge original starter bank','CC BY 4.0','starter-author-v1','starter-review-v1','PUBLISHED');

INSERT INTO interview_seed(id,role_id,kind,topic,prompt,reference_answer,state,reviewer) VALUES
('seed-java-language-1','java-developer','TECHNICAL','java-language','Explain the difference between == and equals in Java.','For objects, == compares references while equals compares logical equality when implemented. Primitive == compares values.','PUBLISHED','starter-review-v1'),
('seed-java-oop-1','java-developer','TECHNICAL','oop','How does composition differ from inheritance, and when would you prefer it?','Inheritance models an is-a relationship. Composition builds behavior from owned collaborators and is often preferred for flexibility and lower coupling.','PUBLISHED','starter-review-v1'),
('seed-java-collections-1','java-developer','TECHNICAL','collections','Compare ArrayList and LinkedList for indexed access and insertion.','ArrayList has constant-time indexed access and may shift elements on insertion. LinkedList traverses for indexed access and inserts efficiently when the node position is known.','PUBLISHED','starter-review-v1'),
('seed-backend-api-1','backend-developer','TECHNICAL','api-design','How would you make a create-order API safe to retry?','Use a client idempotency key, store the accepted result atomically, return it for matching retries, and reject conflicting payloads.','PUBLISHED','starter-review-v1'),
('seed-backend-http-1','backend-developer','TECHNICAL','http','When should an API return HTTP 409 instead of 422?','Use 409 when a request conflicts with current resource state, and 422 when its representation fails semantic validation.','PUBLISHED','starter-review-v1'),
('seed-backend-design-1','backend-developer','TECHNICAL','backend-design','How would you process a long-running task without making the client wait?','Persist a durable job, return its identifier and status, process it in a worker, make retries idempotent, and expose completion status.','PUBLISHED','starter-review-v1'),
('seed-swe-dsa-1','software-engineer','TECHNICAL','dsa-arrays','How would you find two array values that add to a target?','Scan while storing seen values in a hash map; for each value check whether its complement was seen. Expected time is linear and space is linear.','PUBLISHED','starter-review-v1'),
('seed-swe-oop-1','software-engineer','TECHNICAL','oop','What does the dependency inversion principle achieve?','High-level policy depends on abstractions rather than concrete low-level details, reducing coupling to replaceable implementations.','PUBLISHED','starter-review-v1'),
('seed-swe-os-1','software-engineer','TECHNICAL','os-processes','Compare a process and a thread.','A process owns an isolated address space. Threads execute within a process and share its address space while keeping separate stacks and registers.','PUBLISHED','starter-review-v1'),
('seed-hr-intro-1','shared','HR','communication','Tell me about yourself and connect your experience to your target role.','Briefly cover current study or work, one relevant strength or project, and why the role is a logical next step without inventing achievements.','PUBLISHED','starter-review-v1'),
('seed-hr-team-1','shared','HR','communication','Describe a time you worked through a disagreement in a team.','Use a real situation, explain the differing views, describe respectful actions and evidence, and state the result and lesson.','PUBLISHED','starter-review-v1'),
('seed-hr-growth-1','shared','HR','communication','Describe a skill you are improving and the concrete steps you are taking.','Choose a genuine development area, explain a specific practice plan, and mention observable progress without presenting a disguised strength.','PUBLISHED','starter-review-v1');
